<section class="vc-workflow-intro compact" aria-labelledby="inventory-intro-title"><div class="vc-workflow-icon"><i class="fa-solid fa-warehouse"></i></div><div><span class="vc-section-kicker">INVENTORY CONTROL</span><h2 id="inventory-intro-title">Keep sellable stock accurate</h2><p>Physical stock minus reserved customer units is what remains available. Every manual adjustment is recorded with its reason.</p></div></section>
<div class="vc-callout mt-3" id="inventory-message" role="status">Loading your stock…</div>
<section class="vc-grid four mt-3" aria-label="Live inventory summary"><article class="vc-card vc-stat"><span class="vc-stat-label">Available units</span><div class="vc-stat-value" id="inventory-available">—</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Reserved units</span><div class="vc-stat-value" id="inventory-reserved">—</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Low-stock variants</span><div class="vc-stat-value" id="inventory-low">—</div></article><article class="vc-card vc-stat"><span class="vc-stat-label">Out-of-stock variants</span><div class="vc-stat-value" id="inventory-out">—</div></article></section>
<section class="vc-card mt-3"><div class="vc-card-head"><h2>Stock by product variant</h2><div class="vc-toolbar"><div class="vc-search"><i class="fa-solid fa-magnifying-glass"></i><input id="inventory-search" type="search" placeholder="Search product or SKU" aria-label="Search inventory"></div><button type="button" class="vc-btn small" id="inventory-refresh">Refresh</button></div></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Product</th><th>Variant / SKU</th><th>Physical</th><th>Reserved</th><th>Available</th><th>Low-stock level</th><th>Status</th><th>Action</th></tr></thead><tbody id="inventory-rows"><tr><td colspan="8">Loading stock…</td></tr></tbody></table></div></section>
<section class="vc-card mt-3"><div class="vc-card-head"><h2>Recent stock changes</h2></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Date</th><th>Product / SKU</th><th>Change</th><th>Physical after</th><th>Reason</th></tr></thead><tbody id="inventory-movements"><tr><td colspan="5">Loading history…</td></tr></tbody></table></div></section>
<dialog class="vc-dialog" id="inventory-adjust-dialog"><div class="vc-dialog-head"><h2>Adjust stock</h2><button class="vc-btn small" type="button" id="inventory-close">Close</button></div><form class="vc-dialog-body" id="inventory-adjust-form"><div class="vc-callout">Only physical stock changes here. Reserved customer units cannot be removed.</div><div class="vc-form-grid mt-3"><div class="vc-field full"><label for="inventory-variant">Product variant</label><select class="vc-select" id="inventory-variant" required></select></div><div class="vc-field"><label for="inventory-delta">Quantity change</label><input class="vc-input" id="inventory-delta" type="number" min="-100000" max="100000" step="1" required><small>Use a positive number to add stock and a negative number to remove it.</small></div><div class="vc-field full"><label for="inventory-reason">Reason</label><textarea class="vc-textarea" id="inventory-reason" minlength="3" maxlength="500" required></textarea></div></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Save stock change</button></div></form></dialog>
